-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.market_gets_its_rooms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Only real markets. The worldwide shell has its own rooms already.
  if new.kind <> 'chapter' then return new; end if;

  insert into public.channels (community_id, key, label, hint, icon, post_policy, visibility, position)
  values
    (new.id, 'general', 'General',
     'The main room. Everything going on in ' || new.name || '.',
     'chat', 'all', 'scope', -2),
    (new.id, 'announcements', 'Announcements',
     'News for ' || new.name || ' from the team.',
     'megaphone', 'staff', 'scope', -1)
  on conflict (community_id, key) do nothing;

  return new;
end;
$function$;
